<?php
declare(strict_types=1);
require_once __DIR__.'/payments.php';

function tuman_teacher_credits(PDO $db,int $teacherId): array { $s=$db->prepare("SELECT c.*,sp.first_name,sp.last_name FROM tmn_student_credits c INNER JOIN tmn_teacher_students ts ON ts.id=c.teacher_student_id INNER JOIN tmn_student_profiles sp ON sp.user_id=ts.student_user_id WHERE ts.teacher_user_id=:teacher_id ORDER BY c.status='ACTIVE' DESC,c.created_at DESC");$s->execute(['teacher_id'=>$teacherId]);return $s->fetchAll(); }
function tuman_teacher_credit(PDO $db,int $teacherId,int $creditId): ?array { $s=$db->prepare('SELECT c.*,ts.student_user_id,sp.first_name,sp.last_name FROM tmn_student_credits c INNER JOIN tmn_teacher_students ts ON ts.id=c.teacher_student_id INNER JOIN tmn_student_profiles sp ON sp.user_id=ts.student_user_id WHERE c.id=:id AND ts.teacher_user_id=:teacher_id');$s->execute(['id'=>$creditId,'teacher_id'=>$teacherId]);$r=$s->fetch();return is_array($r)?$r:null; }
function tuman_apply_credit(PDO $db,int $teacherId,int $creditId,int $invoiceId,string $amount): void { $minor=tuman_invoice_minor_from_decimal($amount);if($minor===null||$minor<=0)throw new InvalidArgumentException('Enter a credit amount greater than zero.');$db->beginTransaction();try{$credit=tuman_teacher_credit($db,$teacherId,$creditId);$invoice=tuman_locked_teacher_invoice($db,$teacherId,$invoiceId);if($credit===null||$credit['status']!=='ACTIVE'||$invoice===null||!in_array($invoice['status'],['ISSUED','PARTIALLY_PAID'],true)||$credit['teacher_student_id']!=$invoice['teacher_student_id']||$credit['currency_code']!==$invoice['currency_code'])throw new InvalidArgumentException('Credit cannot be applied to that invoice.');$remaining=tuman_invoice_minor_from_decimal($credit['remaining_amount']);$paid=tuman_invoice_valid_payment_minor($db,$invoiceId,$invoice['currency_code']);$a=$db->prepare('SELECT COALESCE(SUM(amount),0) FROM tmn_credit_applications WHERE invoice_id=:id FOR UPDATE');$a->execute(['id'=>$invoiceId]);$applied=tuman_invoice_minor_from_decimal((string)$a->fetchColumn())??0;$due=(tuman_invoice_minor_from_decimal($invoice['total_amount'])??0)-min($paid+$applied,tuman_invoice_minor_from_decimal($invoice['total_amount'])??0);if($minor>$remaining||$minor>$due)throw new InvalidArgumentException('Credit cannot exceed the unused credit or invoice balance.');$db->prepare('INSERT INTO tmn_credit_applications (credit_id,invoice_id,amount) VALUES (:credit,:invoice,:amount)')->execute(['credit'=>$creditId,'invoice'=>$invoiceId,'amount'=>tuman_invoice_decimal_from_minor($minor)]);$left=$remaining-$minor;$db->prepare("UPDATE tmn_student_credits SET remaining_amount=:amount,status=:status WHERE id=:id")->execute(['amount'=>tuman_invoice_decimal_from_minor($left),'status'=>$left===0?'EXHAUSTED':'ACTIVE','id'=>$creditId]);tuman_update_invoice_payment_status($db,$teacherId,$invoice,$paid+$applied+$minor);tuman_log_activity($db,$teacherId,'CREDIT_APPLIED','STUDENT_CREDIT',$creditId,['invoice_id'=>$invoiceId,'amount'=>tuman_invoice_decimal_from_minor($minor),'currency_code'=>$credit['currency_code']]);$db->commit();}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}}
function tuman_refund_credit(PDO $db,int $teacherId,int $creditId,array $input): void { $v=tuman_payment_values($input);$db->beginTransaction();try{$c=tuman_teacher_credit($db,$teacherId,$creditId);if($c===null||$c['status']!=='ACTIVE'||$v['amount_minor']>(tuman_invoice_minor_from_decimal($c['remaining_amount'])??0))throw new InvalidArgumentException('Refund cannot exceed the unused credit.');$db->prepare('INSERT INTO tmn_credit_refunds (credit_id,refund_date,amount,refund_method,reference_number,remarks) VALUES (:credit,:date,:amount,:method,:reference,:remarks)')->execute(['credit'=>$creditId,'date'=>$v['payment_date'],'amount'=>$v['amount'],'method'=>$v['payment_method'],'reference'=>$v['reference_number'],'remarks'=>$v['remarks']]);$left=(tuman_invoice_minor_from_decimal($c['remaining_amount'])??0)-$v['amount_minor'];$db->prepare('UPDATE tmn_student_credits SET remaining_amount=:amount,status=:status WHERE id=:id')->execute(['amount'=>tuman_invoice_decimal_from_minor($left),'status'=>$left===0?'EXHAUSTED':'ACTIVE','id'=>$creditId]);tuman_log_activity($db,$teacherId,'CREDIT_REFUNDED','STUDENT_CREDIT',$creditId,['amount'=>$v['amount'],'currency_code'=>$c['currency_code']]);$db->commit();}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}}
